module bad_apple_frame_rom #(
    parameter integer WIDTH = 64,
    parameter integer HEIGHT = 48,
    parameter integer FRAME_COUNT = 20
) (
    input [4:0] frame_index,
    input [5:0] pixel_x,
    input [5:0] pixel_y,
    output pixel_on
);
    reg [3071:0] frame_mem [0:FRAME_COUNT-1];
    initial begin
        frame_mem[0] = 3072';
        frame_mem[1] = 3072';
        frame_mem[2] = 3072';
        frame_mem[3] = 3072';
        frame_mem[4] = 3072';
        frame_mem[5] = 3072';
        frame_mem[6] = 3072';
        frame_mem[7] = 3072';
        frame_mem[8] = 3072';
        frame_mem[9] = 3072';
        frame_mem[10] = 3072';
        frame_mem[11] = 3072';
        frame_mem[12] = 3072';
        frame_mem[13] = 3072';
        frame_mem[14] = 3072';
        frame_mem[15] = 3072';
        frame_mem[16] = 3072';
        frame_mem[17] = 3072';
        frame_mem[18] = 3072';
        frame_mem[19] = 3072';
    end

    assign pixel_on = (frame_index < FRAME_COUNT) &&
                      (pixel_x < WIDTH) && (pixel_y < HEIGHT) &&
                      frame_mem[frame_index][pixel_y * WIDTH + pixel_x];
endmodule
